CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('online','offline','hybrid')),venue TEXT,join_url TEXT,price_paise INTEGER NOT NULL CHECK(price_paise>0),seats INTEGER NOT NULL CHECK(seats>0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed','cancelled')));
CREATE TABLE IF NOT EXISTS partners(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,code TEXT NOT NULL UNIQUE,commission_bps INTEGER NOT NULL CHECK(commission_bps BETWEEN 0 AND 10000),status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS coupons(code TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('percent','flat')),value INTEGER NOT NULL CHECK(value>0),partner_id TEXT REFERENCES partners(id),max_uses INTEGER,used_count INTEGER NOT NULL DEFAULT 0,valid_from TEXT,valid_to TEXT,active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS registrations(id TEXT PRIMARY KEY,event_id TEXT NOT NULL REFERENCES events(id),contact_id TEXT NOT NULL REFERENCES contacts(id),amount_paise INTEGER NOT NULL CHECK(amount_paise>=0),discount_paise INTEGER NOT NULL DEFAULT 0,coupon_code TEXT REFERENCES coupons(code),partner_id TEXT REFERENCES partners(id),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','failed','refunded','waitlist')),cashfree_order_id TEXT UNIQUE,cashfree_payment_id TEXT UNIQUE,refunded_paise INTEGER NOT NULL DEFAULT 0,attended INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(event_id,contact_id));
CREATE TABLE IF NOT EXISTS commissions(id TEXT PRIMARY KEY,partner_id TEXT NOT NULL REFERENCES partners(id),registration_id TEXT NOT NULL UNIQUE REFERENCES registrations(id),amount_paise INTEGER NOT NULL CHECK(amount_paise>=0),payable_at TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','paid','void')));
CREATE TABLE IF NOT EXISTS certificates(code TEXT PRIMARY KEY,registration_id TEXT NOT NULL UNIQUE REFERENCES registrations(id),holder_name TEXT NOT NULL,programme TEXT NOT NULL,issued_at TEXT NOT NULL,revoked_at TEXT);
CREATE TABLE IF NOT EXISTS payment_events(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,created_at TEXT NOT NULL);
